import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }

        Map<Long, Integer> factor(long nLocal) {
            Map<Long, Integer> d = new HashMap<>();
            for (int p : primes) {
                long pLong = p;
                if (pLong * pLong > nLocal) {
                    break;
                }
                if (nLocal % pLong == 0) {
                    int c = 0;
                    while (nLocal % pLong == 0) {
                        nLocal /= pLong;
                        c++;
                    }
                    d.put(pLong, c);
                }
            }
            if (nLocal > 1) {
                d.put(nLocal, 1);
            }
            return d;
        }

        List<Long> factors(long nLocal) {
            Map<Long, Integer> d = factor(nLocal);
            List<Long> answer = new ArrayList<>();
            answer.add(1L);
            for (Long p : d.keySet()) {
                List<Long> a2 = new ArrayList<>();
                int exp = d.get(p);
                for (Long x : answer) {
                    for (int i = 0; i <= exp; i++) {
                        a2.add(x * pow(p, i));
                    }
                }
                answer = a2;
            }
            return answer;
        }

        long process(int N, int M) {
            Map<Integer, Integer> fDict = new HashMap<>();
            fDict.put(0, 0);
            fDict.put(1, 1);
            fDict.put(2, 2);
            for (int i = 3; i <= N; i++) {
                int value = 2 * fDict.get(i - 1);
                for (long x : factors(i)) {
                    if (2 <= x && x <= i) {
                        int numerator = fDict.get(i / (int) x);
                        int denominator = fDict.get((i - 1) / (int) x);
                        int delta = numerator - denominator;
                        value += delta;
                        value %= M;
                    }
                }
                value = ((value % M) + M) % M;
                fDict.put(i, value);
            }
            return fDict.get(N);
        }

        System.out.println(process(n, m));
        scanner.close();
    }

    private static long pow(long base, int exp) {
        long result = 1;
        for (int i = 0; i < exp; i++) {
            result *= base;
        }
        return result;
    }
}
